clojureSource "java-test/lawspec/testing/check/Generator.java" = "// Generated by LawSpec. Do not edit.\npackage lawspec.testing.check;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.function.Function;\nimport java.util.function.Predicate;\n\n/**\n * LawSpec's generators, in the shape the generated law cases use (JetCheck's\n * names), for test.check. Every random choice is one integer drawn and\n * recorded, so a value's rose tree is made by replaying smaller choices\n * through the same generator: each shrink is a value the generator, and\n * its refinement filters, can make. ref:DEC-clojure-property-library\n */\n@FunctionalInterface\npublic interface Generator<T> {\n  /** One value, from the choices of a draw. */\n  T generateValue(Draws draws);\n\n  /** Values made by code that draws from other generators. */\n  static <T> Generator<T> from(Function<GenerationEnvironment, T> body) {\n    return draws -> body.apply(draws);\n  }\n\n  static <T> Generator<T> constant(T value) {\n    return draws -> value;\n  }\n\n  static Generator<Integer> integers() {\n    return integers(Integer.MIN_VALUE, Integer.MAX_VALUE);\n  }\n\n  static Generator<Integer> integers(int min, int max) {\n    if (min > max) throw new IllegalArgumentException(\"empty range \" + min + \"..\" + max);\n    return draws -> draws.draw(min, max);\n  }\n\n  static Generator<Boolean> booleans() {\n    return draws -> draws.draw(0, 1) == 1;\n  }\n\n  /** Any double: zero, the special values, small integers or any bit pattern. */\n  static Generator<Double> doubles() {\n    return draws -> switch (draws.draw(0, 9)) {\n      case 0 -> 0.0;\n      case 1 -> Double.NaN;\n      case 2 -> Double.POSITIVE_INFINITY;\n      case 3 -> Double.NEGATIVE_INFINITY;\n      case 4 -> -0.0;\n      case 5 -> (double) draws.draw(-1000, 1000);\n      default -> Double.longBitsToDouble(\n          ((long) draws.draw(Integer.MIN_VALUE, Integer.MAX_VALUE) << 32)\n              | (draws.draw(Integer.M