clojureSource "java-test/lawspec/testing/check/PropertyChecker.java" = "// Generated by LawSpec. Do not edit.\npackage lawspec.testing.check;\n\nimport clojure.java.api.Clojure;\nimport clojure.lang.IFn;\nimport java.util.function.IntUnaryOperator;\nimport java.util.function.Predicate;\n\n/**\n * Runs a property on test.check (lawspec.check/quick-check): test.check\n * draws the seeds and sizes, runs the cases and walks the rose tree of a\n * failure to its smallest case. LAWSPEC_SEED (passed with withSeed) repeats\n * a run.\n */\npublic final class PropertyChecker {\n  private PropertyChecker() {}\n\n  private static IFn check;\n\n  public static <T> void forAll(Generator<T> generator, Predicate<T> property) {\n    customized().forAll(generator, property);\n  }\n\n  public static Parameters customized() {\n    return new Parameters(null, 100);\n  }\n\n  private static synchronized IFn check() {\n    if (check == null) {\n      Clojure.var(\"clojure.core\", \"require\").invoke(Clojure.read(\"lawspec.check\"));\n      check = Clojure.var(\"lawspec.check\", \"quick-check\");\n    }\n    return check;\n  }\n\n  /** How many cases, and from which seed. */\n  public static final class Parameters {\n    private final Long seed;\n    private final int iterations;\n\n    Parameters(Long seed, int iterations) {\n      this.seed = seed;\n      this.iterations = iterations;\n    }\n\n    public Parameters withSeed(long seed) {\n      return new Parameters(seed, iterations);\n    }\n\n    public Parameters withIterationCount(int iterations) {\n      return new Parameters(seed, iterations);\n    }\n\n    /** test.check sizes the cases itself, from 0 to 100 over the run. */\n    public Parameters withSizeHint(IntUnaryOperator sizeHint) {\n      return this;\n    }\n\n    public <T> void forAll(Generator<T> generator, Predicate<T> property) {\n      check().invoke(generator, property, iterations, seed);\n    }\n  }\n}\n"
clojureSource "src/lawspec/build.clj" = ";; Generated by LawSpec. Do not edit.\n(ns lawspec.build\n  \"Compiles the Java model with the JDK's compiler: java/src into\n  target/classes and java/test into target/test-classes, when a source is\n  newer than the last compilation. Both are on the classpath deps.edn gives.\"\n  (:require [clojure.java.io :as io]\n            [clojure.string :as str])\n  (:import (java.net URL URLClassLoader)\n           (javax.tools ToolProvider)))\n\n(defn- sources [root]\n  (let [dir (io/file root)]\n    (if (.isDirectory dir)\n      (->> (file-seq dir) (filter #(str/ends-with? (.getName ^java.io.File %) \".java\")) (sort-by str) vec)\n      [])))\n\n(defn- stale? [files stamp]\n  (let [stamp (io/file stamp)]\n    (or (not (.exists stamp))\n        (some #(> (.lastModified ^java.io.File %) (.lastModified stamp)) files))))\n\n(defn- javac!\n  \"Compiles a tree when it is stale, or when forced; true when it did.\"\n  [root out force?]\n  (let [files (sources root)\n        stamp (str out \".stamp\")]\n    (when (and (seq files) (or force? (stale? files stamp)))\n      (.mkdirs (io/file out))\n      (let [compiler (or (ToolProvider/getSystemJavaCompiler)\n                         (throw (ex-info \"LawSpec needs a JDK: no Java compiler is available\" {})))\n            arguments (into [\"-d\" out \"-cp\" (System/getProperty \"java.class.path\")\n                             \"-encoding\" \"UTF-8\" \"-proc:none\" \"-nowarn\" \"-Xlint:none\"]\n                            (map str files))\n            status (.run compiler nil nil nil (into-array String arguments))]\n        (when-not (zero? status)\n          (throw (ex-info (str \"javac failed on \" root) {:root root})))\n        (spit stamp \"\")\n        true))))\n\n(defn compile-java!\n  \"Compiles the model, and with tests? its law cases and test support.\"\n  ([] (compile-java! true))\n  ([tests?]\n   (let [model? (javac! \"java/src\" \"target/classes\" false)]\n     (when tests? (javac! \"java/test\" \"target/test-classes\" model?)))))\n\n(defn use-classes!\n  \"Makes the compiled model (and with tests? the law cases) loadable by this\n  thread and the code it loads: a JVM started before the first compilation\n  has no class directories on its classpath yet.\"\n  ([] (use-classes! true))\n  ([tests?]\n   (let [dirs (cond-> [\"target/classes\"] tests? (conj \"target/test-classes\"))\n         urls (into-array URL (map #(.toURL (.toURI (io/file (str % \"/\")))) dirs))\n         thread (Thread/currentThread)]\n     (.setContextClassLoader thread (URLClassLoader. urls (.getContextClassLoader thread))))))\n\n(defn -main [& _]\n  (compile-java! false)\n  (shutdown-agents))\n"
clojureSource "src/lawspec/clojure.clj" = ";; Generated by LawSpec. Do not edit.\n(ns lawspec.clojure\n  \"Clojure's side of the Java model. Values cross as Clojure data: a data\n  type's value is a map whose :lawspec/tag names its constructor, as\n  {:lawspec/tag :payment/approved, :cents 500}, and whose other keys name\n  its fields; a constructor without fields is its tag alone,\n  :payment/declined. Lists are vectors, sets and key-value maps are\n  Clojure's, integers are longs or bigints, Maybe is nil or the value, and\n  Either is [:left x] or [:right x]. An adapter fails with (fail ...): an\n  ex-info whose data holds :lawspec/failure.\n  ref:DEC-clojure-over-java\"\n  (:import (lawspec.clojure LawSpecClojure)))\n\n(defn fail\n  \"Fails with a typed failure: the failure constructor's data, as\n  {:lawspec/tag :payment-error/too-large} or :payment-error/too-large.\"\n  ([failure] (fail failure \"failed\"))\n  ([failure message]\n   (throw (ex-info (str message \": \" (pr-str failure)) {:lawspec/failure failure}))))\n\n(defn op\n  \"Calls an operation of an ability handler the model passes an adapter:\n  (op gateway :capture 500).\"\n  [handler operation & arguments]\n  (LawSpecClojure/call handler (name operation) (object-array arguments)))\n\n(defn definition\n  \"A checked definition of the model as a Clojure function of Clojure data:\n  ((definition lawspec.definitions.example.Total \\\"size\\\") {} [1 2]).\n  Its first argument is the Symbol context, a map shared across calls.\"\n  [owner method]\n  (fn [& arguments]\n    (LawSpecClojure/callStatic owner method (object-array arguments))))\n\n(defn ->clojure\n  \"A value of the Java model as Clojure data.\"\n  [value]\n  (LawSpecClojure/toClojure value))\n\n(defn tag\n  \"The constructor of a data type's value: its :lawspec/tag, or the keyword\n  itself for a constructor without fields.\"\n  [value]\n  (if (keyword? value) value (:lawspec/tag value)))\n"
clojureSource "test/lawspec/check.clj" = ";; Generated by LawSpec. Do not edit.\n(ns lawspec.check\n  \"LawSpec's generators on test.check. A generator of the law cases becomes a\n  test.check generator of rose trees: the root is a case drawn from\n  test.check's random source and size, and its children are the smaller\n  cases LawSpec can make again, so a shrink never leaves a refinement.\n  quick-check runs a law's property and throws an AssertionError naming the\n  smallest failing case and the seed that repeats the run.\"\n  (:require [clojure.test.check :as tc]\n            [clojure.test.check.generators :as gen]\n            [clojure.test.check.properties :as prop]\n            [clojure.test.check.random :as random]\n            [clojure.test.check.rose-tree :as rose])\n  (:import (java.util Iterator)\n           (java.util.function Predicate)\n           (lawspec.testing.check Draws$Case Generator)))\n\n(defn- tree\n  \"The rose tree of a case: its value, and lazily the trees of its shrinks.\"\n  [^Draws$Case c]\n  (rose/make-rose (.value c) (map tree (iterator-seq (.shrinks c)))))\n\n(defn generator\n  \"A test.check generator of a LawSpec generator's cases.\"\n  [^Generator g]\n  (gen/->Generator\n    (fn [rnd size]\n      (tree (Draws$Case/generate g (random/rand-long rnd) (int size))))))\n\n(defn- message [result]\n  (let [shrunk (:shrunk result)\n        failure (:result shrunk)]\n    (str \"Property falsified after \" (:num-tests result) \" cases (seed \" (:seed result)\n         \"; LAWSPEC_SEED=\" (:seed result) \" repeats the run)\\n\"\n         \"Smallest case: \" (pr-str (first (:smallest shrunk)))\n         (when (instance? Throwable failure) (str \"\\n\" (.getMessage ^Throwable failure))))))\n\n(defn quick-check\n  \"Checks a property of a generator's values with test.check.\"\n  [^Generator g ^Predicate property iterations seed]\n  (let [checked (prop/for-all* [(generator g)] (fn [value] (.test property value)))\n        result (apply tc/quick-check iterations checked :max-size 100 (when seed [:seed seed]))]\n    (when-not (:pass? result)\n      (let [failure (:result (:shrunk result))]\n        (throw (AssertionError. ^String (message result)\n                                ^Throwable (when (instance? Throwable failure) failure)))))\n    nil))\n"
clojureSource "test/lawspec/test.clj" = ";; Generated by LawSpec. Do not edit.\n(ns lawspec.test\n  \"Runs the law cases the Java model's test support compiles, as clojure.test\n  tests: each test calls one case, and a failure it throws fails the test\n  with the law's message. A unit's tests run in their order, in one its\n  seed chooses (order random), or at the same time (parallel).\"\n  (:require [clojure.test :as t])\n  (:import (java.util ArrayList Collections Random)))\n\n(defn cases\n  \"The law cases of a unit: an instance of the class the Java model's test\n  support compiles.\"\n  [class-name]\n  (let [type (Class/forName class-name true (.getContextClassLoader (Thread/currentThread)))]\n    (.newInstance (.getConstructor type (make-array Class 0)) (object-array 0))))\n\n(defn holds\n  \"Runs one of a law's tests: the case method of that name.\"\n  [cases method]\n  (try\n    (clojure.lang.Reflector/invokeInstanceMethod cases method (object-array 0))\n    (t/do-report {:type :pass})\n    (catch Throwable e\n      (t/do-report {:type :fail :message (str (.getMessage e)) :expected (symbol method) :actual e}))))\n\n(defn skip\n  \"A test the harness skips, with its reason.\"\n  [reason]\n  (t/do-report {:type :lawspec/skip :message reason}))\n\n(defmethod t/report :lawspec/skip [m]\n  (t/with-test-out (println \"SKIPPED\" (t/testing-vars-str m) \"-\" (:message m))))\n\n(defn- order-seed [unit]\n  (try\n    (long (clojure.lang.Reflector/invokeStaticMethod \"lawspec.testing.LawSpecHarness\" \"orderSeed\" (object-array 0)))\n    (catch Throwable _\n      (or (some-> (System/getenv \"LAWSPEC_SEED\") parse-long)\n          (.nextInt (Random.) Integer/MAX_VALUE)))))\n\n(defn run\n  \"Runs a unit's tests by its schedule.\"\n  [unit tests {:keys [order parallel]}]\n  (let [tests (if (= order :random)\n                (let [seed (order-seed unit)\n                      shuffled (ArrayList. ^java.util.Collection (sort-by #(str (:name (meta %))) tests))]\n                  (Collections/shuffle shuffled (Random. (bit-xor seed (.hashCode ^String unit))))\n                  (println (str \"order random seed \" seed \" (\" unit \"): LAWSPEC_SEED=\" seed \" replays this order\"))\n                  (vec shuffled))\n                tests)]\n    (if parallel\n      (run! deref (mapv #(future-call (bound-fn [] (t/test-var %))) tests))\n      (run! t/test-var tests))))\n"
clojureSource "test/lawspec/test_runner.clj" = ";; Generated by LawSpec. Do not edit.\n(ns lawspec.test-runner\n  \"clojure -M:test: compiles the Java model, runs every test namespace on the\n  classpath (or the tests --select ns/prefix names), prints clojure.test's\n  report and writes JUnit XML to target/test-results.\"\n  (:require [clojure.java.io :as io]\n            [clojure.string :as str]\n            [clojure.test :as t]\n            [lawspec.build :as build]\n            [lawspec.test :as law]))\n\n(defn- namespaces\n  \"The test namespaces in the classpath's directories: files named *_test.clj.\"\n  []\n  (->> (str/split (System/getProperty \"java.class.path\") (re-pattern (java.io.File/pathSeparator)))\n       (map io/file)\n       (filter #(.isDirectory ^java.io.File %))\n       (mapcat (fn [^java.io.File root]\n                 (let [base (count (str (.getCanonicalPath root) \"/\"))]\n                   (for [^java.io.File f (file-seq root)\n                         :let [path (.getCanonicalPath f)]\n                         :when (str/ends-with? path \"_test.clj\")]\n                     (-> path (subs base (- (count path) 4)) (str/replace \"/\" \".\") (str/replace \"_\" \"-\") symbol)))))\n       distinct\n       sort))\n\n(defn- escape [s]\n  (-> (str s) (str/replace \"&\" \"&amp;\") (str/replace \"<\" \"&lt;\") (str/replace \">\" \"&gt;\") (str/replace \"\\\"\" \"&quot;\")))\n\n(defn- junit [ns-name results]\n  (let [cases (sort-by first results)\n        count-of (fn [k] (count (filter #(seq (k (second %))) cases)))]\n    (str \"<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n\"\n         \"<testsuite name=\\\"\" (escape ns-name) \"\\\" tests=\\\"\" (count cases) \"\\\" failures=\\\"\" (count-of :failures)\n         \"\\\" errors=\\\"\" (count-of :errors) \"\\\" skipped=\\\"\" (count (filter #(:skipped (second %)) cases)) \"\\\">\\n\"\n         (apply str\n           (for [[test {:keys [time failures errors skipped]}] cases]\n             (str \"  <testcase name=\\\"\" (escape test) \"\\\" classname=\\\"\" (escape ns-name) \"\\\" time=\\\"\" (format \"%.3f\" (double (or time 0))) \"\\\"\"\n                  (if (or skipped (seq failures) (seq errors))\n                    (str \">\\n\"\n                         (when skipped (str \"    <skipped message=\\\"\" (escape skipped) \"\\\"/>\\n\"))\n                         (apply str (for [m failures] (str \"    <failure message=\\\"\" (escape (:message m)) \"\\\">\" (escape (:text m)) \"</failure>\\n\")))\n                         (apply str (for [m errors] (str \"    <error message=\\\"\" (escape (:message m)) \"\\\">\" (escape (:text m)) \"</error>\\n\")))\n                         \"  </testcase>\\n\")\n                    \"/>\\n\"))))\n         \"</testsuite>\\n\")))\n\n(defn- trace [x]\n  (if (instance? Throwable x)\n    (let [w (java.io.StringWriter.)] (.printStackTrace ^Throwable x (java.io.PrintWriter. w)) (str w))\n    (pr-str x)))\n\n(defn- recording [results base]\n  (fn [m]\n    (let [v (first t/*testing-vars*)\n          k (when v [(str (:ns (meta v))) (str (:name (meta v)))])]\n      (case (:type m)\n        :begin-test-var (swap! results assoc-in [k :start] (System/nanoTime))\n        :end-test-var (swap! results update k #(assoc % :time (/ (- (System/nanoTime) (:start % 0)) 1e9)))\n        :fail (swap! results update-in [k :failures] conj {:message (:message m) :text (trace (:actual m))})\n        :error (swap! results update-in [k :errors] conj {:message (str (:message m) (when (instance? Throwable (:actual m)) (.getMessage ^Throwable (:actual m)))) :text (trace (:actual m))})\n        :lawspec/skip (swap! results assoc-in [k :skipped] (:message m))\n        nil)\n      (base m))))\n\n(defn- selected? [selections v]\n  (or (empty? selections)\n      (let [{:keys [ns name]} (meta v)\n            full (str (ns-name ns) \"/\" name)]\n        (some #(str/starts-with? full %) selections))))\n\n(defn- run-namespace [ns selections]\n  (let [tests (or (some-> (ns-resolve ns 'lawspec-tests) deref)\n                  (->> (ns-interns ns) vals (filter (comp :test meta)) (sort-by (comp str :name meta))))\n        schedule (or (some-> (ns-resolve ns 'lawspec-schedule) deref) {})\n        chosen (filter #(selected? selections %) tests)]\n    (when (seq chosen)\n      (t/do-report {:type :begin-test-ns :ns (the-ns ns)})\n      (law/run (str (ns-name ns)) (vec chosen) schedule)\n      (t/do-report {:type :end-test-ns :ns (the-ns ns)}))))\n\n(defn -main [& args]\n  (let [selections (->> (partition 2 args) (filter #(= \"--select\" (first %))) (map second))\n        exit (atom 1)]\n    (try\n      (build/compile-java!)\n      (build/use-classes!)\n      (let [nss (namespaces)\n            nss (if (seq selections) (filter (fn [n] (some #(str/starts-with? % (str n \"/\")) selections)) nss) nss)\n            results (atom {})]\n        (doseq [n nss] (require n))\n        (binding [t/*report-counters* (ref t/*initial-report-counters*)]\n          (binding [t/report (recording results t/report)]\n            (doseq [n nss] (run-namespace n selections)))\n          (let [counters @t/*report-counters*]\n            (.mkdirs (io/file \"target/test-results\"))\n            (doseq [[ns-name cases] (group-by ffirst (dissoc @results nil))]\n              (spit (str \"target/test-results/TEST-\" ns-name \".xml\")\n                    (junit ns-name (for [[[_ test] r] cases] [test r]))))\n            (t/do-report (assoc counters :type :summary))\n            (reset! exit (if (zero? (+ (:fail counters) (:error counters))) 0 1)))))\n      (catch Throwable e\n        (binding [*out* *err*]\n          (println (if (instance? clojure.lang.Compiler$CompilerException e) \"Syntax error compiling\" \"Error:\") (.getMessage e))\n          (some-> (.getCause e) .getMessage println))\n        (reset! exit 1)))\n    (shutdown-agents)\n    (System/exit @exit)))\n"
